INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(38111, 'Psalms 93:1', 'Psalms', 93, 1, 'څښتن کوي پاچاهي هغه اغوستې د جلال چپنه څښتن اغوستې ده چپنه او په قوت یې خپله ملا تړلې په رښتیا نړۍ یې ټینګه ودرولې هغه هېڅکله خوځېدلې نه شي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms93_verse_1.mp3', '', 1761754199, 1761754199),
(38112, 'Psalms 93:2', 'Psalms', 93, 2, 'ای څښتنه تخت دې قایم دی له ډېر پخوا نه ته موجود وې له ازله', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms93_verse_2.mp3', '', 1761754199, 1761754199),
(38113, 'Psalms 93:3', 'Psalms', 93, 3, 'راپورته شوي سېلابونه ای څښتنه! راپورته کړی سېلابونو خپل غږ اوچت کړی سېلابونو غړمبار دی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms93_verse_3.mp3', '', 1761754199, 1761754199),
(38114, 'Psalms 93:4', 'Psalms', 93, 4, 'څښتن قوي دی د دریاب د شورماشور څخه هغه قوي دی د دریاب له څپو دی زورور د اسمانونو څښتن', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms93_verse_4.mp3', '', 1761754199, 1761754199),
(38115, 'Psalms 93:5', 'Psalms', 93, 5, 'ډېر باوري دي حکمونه د ستا سپېڅلتوب دی تل ترتله ستا د کور ښایست څښتنه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms93_verse_5.mp3', '', 1761754199, 1761754199),
(38116, 'Zechariah 9:1', 'Zechariah', 9, 1, 'د مالِک خُدائ پېغام د حدرک د مُلک خلاف دے او دا به په دمشق نازل شى، ځکه چې د خلقو او د بنى اِسرائيلو د ټولو قبيلو سترګې مالِک خُدائ ته دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah9_verse_1.mp3', '', 1761754199, 1761754199),
(38117, 'Zechariah 9:2', 'Zechariah', 9, 2, 'او حمات ته هم چې د دې سره يې سرحدونه دى، او په صور او صيدا هم اګر کۀ هغوئ ډېر ماهران دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah9_verse_2.mp3', '', 1761754199, 1761754199),
(38118, 'Zechariah 9:3', 'Zechariah', 9, 3, 'د صور خلقو ځان دپاره پخه قلعه جوړه کړه، او هغې سپين زر لکه د خاورې ډيرى، او سرۀ زر يې لکه د کوڅو د ګندونو په شان راغونډ کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah9_verse_3.mp3', '', 1761754199, 1761754199),
(38119, 'Zechariah 9:4', 'Zechariah', 9, 4, 'خو مالِک خُدائ به د دې ملکيت قبضه کړى. او د دې ټول قدرت به په سمندر کښې تباه کړى، او دا به په اور وسوزولے شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah9_verse_4.mp3', '', 1761754199, 1761754199),
(38120, 'Zechariah 9:5', 'Zechariah', 9, 5, 'د اسقلون ښار به دا وګورى او وبه يريږى. غزه به د يرې نه په لړزان شى. او عقرون به هم، ځکه چې د هغې اُميد به ختم شى. د غزه بادشاه به مړ شى او اسقلون به شاړ شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah9_verse_5.mp3', '', 1761754199, 1761754199),
(38121, 'Zechariah 9:6', 'Zechariah', 9, 6, 'پردى خلق به اشدود قبضه کړى، او زۀ به د فلستيانو غرور ختم کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah9_verse_6.mp3', '', 1761754199, 1761754199),
(38122, 'Zechariah 9:7', 'Zechariah', 9, 7, 'زۀ به د هغوئ د خُلو نه د وينو ډکه غوښه راکاږم، او د هغوئ د غاښونو نه به حرامه قربانى راوباسم. او ژوندى پاتې شوى فلستيان به زمونږ د مالِک خُدائ عبادت وکړى او د يهوداه د يوې قبيلې په شان به شى. د عقرون فلستيان به زما خلقو سره يوځائ شى، لکه څنګه چې پخوانى يبوسى يو ځلى يوځائ شوى وُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah9_verse_7.mp3', '', 1761754199, 1761754199),
(38123, 'Zechariah 9:8', 'Zechariah', 9, 8, 'نو زۀ به د حمله کوونکى لښکر خلاف د خپل کور حِفاظت کوم. زما په خلقو به بيا هيڅکله ظالمان راونۀ خېژى، ځکه چې زۀ اوس په خپله د دې حفاظت کوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah9_verse_8.mp3', '', 1761754199, 1761754199),
(38124, 'Zechariah 9:9', 'Zechariah', 9, 9, 'ډېره خوشحالى وکړه، اے صيون لورې. د خوشحالۍ نه چغې ووهه، د يروشلم لورې. وګورئ، ستاسو بادشاه تاسو ته راروان دے، هغه صادق او خلاصونکے دے، هغه حليم او په خرۀ سور دے، په کوچاڼى يعنې په کوچى باندې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah9_verse_9.mp3', '', 1761754199, 1761754199),
(38125, 'Zechariah 9:10', 'Zechariah', 9, 10, 'زۀ به د اِفرائيم نه جنګى ګاډۍ بوځم او جنګى آسونه به د يروشلم نه بوځم، او جنګى ليندې به ماتې کړے شى. هغه به قومونو ته د امن اعلان وکړى. د هغۀ بادشاهى به د يو سمندر نه بل سمندر پورې لويه شى او د فرات سيند نه به تر د دُنيا آخرى حدودو پورې وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah9_verse_10.mp3', '', 1761754199, 1761754199),
(38126, 'Zechariah 9:11', 'Zechariah', 9, 11, 'اے زما قومه، ما تاسو سره لوظ وکړو او د هغې تصديق د قربانۍ وينې سره وشو، د دې دپاره چې زۀ به ستاسو قېديان د اوچ کندو نه آزاد کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah9_verse_11.mp3', '', 1761754199, 1761754199),
(38127, 'Zechariah 9:12', 'Zechariah', 9, 12, 'خپلې قلعې ته په اُميد سره واپس راشئ، اے قېديانو، زۀ هم اوس اعلان کوم چې تاسو به زۀ يو په دوه بيا آباد کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah9_verse_12.mp3', '', 1761754199, 1761754199),
(38128, 'Zechariah 9:13', 'Zechariah', 9, 13, 'زۀ به يهوداه داسې راکاږم لکه څنګه چې زۀ خپله د غشى لينده راکاږم او د اِفرائيم نه به يې لکه د غشو ډک کړم. زۀ به ستا زامن، اے صيونه، د يونان د زامنو خلاف راپاروم، او تا نه به د جنګيالى تُوره جوړه کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah9_verse_13.mp3', '', 1761754199, 1761754199),
(38129, 'Zechariah 9:14', 'Zechariah', 9, 14, 'بيا مالِک خُدائ به د هغوئ دپاسه راښکاره شى، د هغۀ غشى به لکه د برېښنا په شان ځليږى. مالِک خُدائ ربُ الافواج به بيګل وغږوى، هغه به د جنوب طرف طوفان کښې راشى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah9_verse_14.mp3', '', 1761754199, 1761754199),
(38130, 'Zechariah 9:15', 'Zechariah', 9, 15, 'او مالِک خُدائ ربُ الافواج به د هغوئ حِفاظت کوى، هغوئ به دشمنان تباه کړى او په هغوئ به د ليندو کاڼو سره غالب شى. هغوئ به د شرابيانو په شان شور کوى، هغوئ به لکه د هغه جام په شان ډک وى چې د قربان‌ګاه په ګوټونو د وينې شيندلو دپاره استعماليږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah9_verse_15.mp3', '', 1761754199, 1761754199),
(38131, 'Zechariah 9:16', 'Zechariah', 9, 16, 'مالِک خُدائ د هغوئ خُدائ پاک به هغوئ په هغه ورځ د خپلو خلقو د شپونکى په توګه بچ کړى. هغوئ به د هغۀ په مُلک کښې لکه د تاج د قيمتى کاڼو په شان ځليږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah9_verse_16.mp3', '', 1761754199, 1761754199),
(38132, 'Zechariah 9:17', 'Zechariah', 9, 17, 'هغوئ به څومره ښکلې او ښائسته وى. غله به ځوانان سړى، او نوى مے به ځوانې ښځې څربه کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah9_verse_17.mp3', '', 1761754199, 1761754199),
(38133, 'Proverbs 6:1', 'Proverbs', 6, 1, 'ای زما زویه! که د چا ضمانت دې په غاړه اخیستی وي یا دې د پردي سړي په قرض کې چاته لاس ورکړی وي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs6_verse_1.mp3', '', 1761754199, 1761754199),
(38134, 'Proverbs 6:2', 'Proverbs', 6, 2, 'نو د خپلې ژبې د خبرې له امله په دام کې رانیول شوی یې او د خپلې خولې د خبرو په لومه کې نښتی یې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs6_verse_2.mp3', '', 1761754199, 1761754199),
(38135, 'Proverbs 6:3', 'Proverbs', 6, 3, 'نو ای زما زویه! بیا داسې وکړه چې ځان ترې وژغوره ځکه چې ته د هغه سړي په لاسونو کې لوېدلی یې: هغه ته په ډېره عاجزۍ ورشه او عذر زاري ورته وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs6_verse_3.mp3', '', 1761754199, 1761754199),
(38136, 'Proverbs 6:4', 'Proverbs', 6, 4, 'مه ویده کېږه او یوه شېبه هم ارام مه کوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs6_verse_4.mp3', '', 1761754199, 1761754199),
(38137, 'Proverbs 6:5', 'Proverbs', 6, 5, 'لکه د هوسۍ په شان ځان د ښکاري له منګولو وژغوره او د مرغۍ په څېر ځان د دام لرونکي له لاسه خلاص کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs6_verse_5.mp3', '', 1761754199, 1761754199),
(38138, 'Proverbs 6:6', 'Proverbs', 6, 6, 'ای لټ سړیه! د مېږي له ژوند نه عبرت واخله د هغه په لارو چارو غور وکړه او حکمت پیدا کړه!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs6_verse_6.mp3', '', 1761754199, 1761754199),
(38139, 'Proverbs 6:7', 'Proverbs', 6, 7, 'میږی نه کوم قوماندان لري او نه کوم مشر او نه کوم آمر لري', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs6_verse_7.mp3', '', 1761754199, 1761754199),
(38140, 'Proverbs 6:8', 'Proverbs', 6, 8, 'خو د لو په وخت کې خپل خواړه راټولوي او په اوړي کې ځان ته خوراک ذخیره کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs6_verse_8.mp3', '', 1761754199, 1761754199),
(38141, 'Proverbs 6:9', 'Proverbs', 6, 9, 'نو ته لټ به ترڅو پورې پروت یې او کله به له خوبه راپاڅېږې؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs6_verse_9.mp3', '', 1761754199, 1761754199),
(38142, 'Proverbs 6:10', 'Proverbs', 6, 10, 'که ته وایې: «نور به هم ویده شم او لاس به د سر لاندې کېږدم چې ارام وکړم»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs6_verse_10.mp3', '', 1761754199, 1761754199),
(38143, 'Proverbs 6:11', 'Proverbs', 6, 11, 'نو غریبي به د داړه مار په شان په تا راشي او نېستي به د وسله وال غل په څېر درباندې یرغل وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs6_verse_11.mp3', '', 1761754199, 1761754199),
(38144, 'Proverbs 6:12', 'Proverbs', 6, 12, 'شر اچوونکی انسان بېکاره او بېځایه ګرځي او په خوله کږې وږې خبرې کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs6_verse_12.mp3', '', 1761754199, 1761754199),
(38145, 'Proverbs 6:13', 'Proverbs', 6, 13, 'هغه سترګې وهي او بېځایه پښې دربوي او په ګوتو اشارې کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs6_verse_13.mp3', '', 1761754199, 1761754199),
(38146, 'Proverbs 6:14', 'Proverbs', 6, 14, 'په خپل زړه کې تل بدې نقشې جوړوي او جنګ او جګړې ته لمن وهي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs6_verse_14.mp3', '', 1761754199, 1761754199),
(38147, 'Proverbs 6:15', 'Proverbs', 6, 15, 'نو ځکه به سمدلاسه لوی مصیبت پرې نازل شي او ناڅاپه به ټوټې ټوټې شي چې د جوړېدو به نه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs6_verse_15.mp3', '', 1761754199, 1761754199),
(38148, 'Proverbs 6:16', 'Proverbs', 6, 16, 'شپږ شیان دي چې څښتن ترې نفرت کوي او اووه شیان دي چې د هغه په نظر د کرکې وړ دي:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs6_verse_16.mp3', '', 1761754199, 1761754199),
(38149, 'Proverbs 6:17', 'Proverbs', 6, 17, 'کبرجنې سترګې او دروغجنه ژبه او هغه لاسونه چې بې‌ګناه وینه تویوي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs6_verse_17.mp3', '', 1761754199, 1761754199),
(38150, 'Proverbs 6:18', 'Proverbs', 6, 18, 'هغه زړه چې بدې نقشې جوړوي او هغه پښې چې د بدۍ په لور په بیړه منډې وهي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs6_verse_18.mp3', '', 1761754199, 1761754199),
(38151, 'Proverbs 6:19', 'Proverbs', 6, 19, 'هغه دروغجن شاهد چې تل دروغ بادوي او هغه څوک چې د ورونو ترمنځ جګړو ته لمن وهي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs6_verse_19.mp3', '', 1761754199, 1761754199),
(38152, 'Proverbs 6:20', 'Proverbs', 6, 20, 'نو ای زما زویه! د خپل پلار په حکم عمل وکړه او د خپلې مور روزنه له پامه مه غورځوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs6_verse_20.mp3', '', 1761754199, 1761754199),
(38153, 'Proverbs 6:21', 'Proverbs', 6, 21, 'د هغوی خبرې تل په خپل زړه کې یاد ساته او د هار په شان یې په خپله غاړه کې ګرځوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs6_verse_21.mp3', '', 1761754199, 1761754199),
(38154, 'Proverbs 6:22', 'Proverbs', 6, 22, 'کله چې ګرځې نو خبرې به یې درته لارښوونه کوي کله چې ویده شې نو روزنه به یې ستا ساتنه کوي او کله چې راویښ شې نو حکم به یې مشوره درکوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs6_verse_22.mp3', '', 1761754199, 1761754199),
(38155, 'Proverbs 6:23', 'Proverbs', 6, 23, 'ځکه حکم یې ډېوه او روزنه یې رڼا ده نصیحت او سختې خبرې یې د ژوندون لار ده', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs6_verse_23.mp3', '', 1761754199, 1761754199),
(38156, 'Proverbs 6:24', 'Proverbs', 6, 24, 'ترڅو تا د بدلمنې ښځې نه وساتي له هغې ښځې نه چې نرمه ژبه لري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs6_verse_24.mp3', '', 1761754199, 1761754199),
(38157, 'Proverbs 6:25', 'Proverbs', 6, 25, 'په زړه کې د هغې د ښایست شوق مه کوه او هغه مه پرېږده چې په سترګې وهلو دې د ځان غلام کړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs6_verse_25.mp3', '', 1761754199, 1761754199),
(38158, 'Proverbs 6:26', 'Proverbs', 6, 26, 'ځکه بدلمنه ښځه د یوې ډوډۍ په بیه اخیستل کیږي خو د بل چا ښځه به دې قیمتي ژوند ښکار کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs6_verse_26.mp3', '', 1761754199, 1761754199),
(38159, 'Proverbs 6:27', 'Proverbs', 6, 27, 'څوک په خپل لمن کې بل شوی اور وړلی شي او کالي یې ونه سوځیږي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs6_verse_27.mp3', '', 1761754199, 1761754199),
(38160, 'Proverbs 6:28', 'Proverbs', 6, 28, 'او یا څوک په سرو سکروټو ګرځېدلی شي چې پښې یې په اور تڼاکې نه شي؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs6_verse_28.mp3', '', 1761754199, 1761754199),
(38161, 'Proverbs 6:29', 'Proverbs', 6, 29, 'نو دا د هغه چا په شان دی چې د بل له ښځې سره څملي هرڅوک چې هغې ته لاس وروړي بې‌سزا به پاتې نه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs6_verse_29.mp3', '', 1761754199, 1761754199),
(38162, 'Proverbs 6:30', 'Proverbs', 6, 30, 'څوک چې د نس د مړېدو په خاطر غلا کوي نو خلک هغه غل ته په سپکه سترګه نه ګوري', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs6_verse_30.mp3', '', 1761754199, 1761754199),
(38163, 'Proverbs 6:31', 'Proverbs', 6, 31, 'خو که ونیول شي نو اووه چنده بیه به ورکوي او په بدل کې به یې د خپل کور ټوله شتمني خرڅوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs6_verse_31.mp3', '', 1761754199, 1761754199),
(38164, 'Proverbs 6:32', 'Proverbs', 6, 32, 'څوک چې د بل له ښځې سره زنا کوي نو ناپوهه دی څوک چې داسې کوي نو په حقیقت کې ځان تباه کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs6_verse_32.mp3', '', 1761754199, 1761754199),
(38165, 'Proverbs 6:33', 'Proverbs', 6, 33, 'هغه به له رسوایۍ او وهلو څخه خلاص نه شي او بې‌عزتي به ترې لېرې نه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs6_verse_33.mp3', '', 1761754199, 1761754199),
(38166, 'Proverbs 6:34', 'Proverbs', 6, 34, 'نو کینه او غیرت به یې په مېړه اور بل کړي او زړه به یې په بدل اخیستلو کې هېڅکله ونه سوځیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs6_verse_34.mp3', '', 1761754199, 1761754199),
(38167, 'Proverbs 6:35', 'Proverbs', 6, 35, 'هغه به د دې په بدل کې هېڅ ډول قرباني قبوله نه کړي او هرڅه چې ورکړې وبه یې نه مني.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs6_verse_35.mp3', '', 1761754199, 1761754199),
(38168, 'Joshua 5:1', 'Joshua', 5, 1, 'د اموریانو ټولو پاچاهانو چې د اردن د سیند په لوېدیځ کې وو او د کنعانیانو ټولو پاچاهانو چې د مدیترانې د بحیرې په غاړه وو، واورېدل چې څښتن د اردن سیند تر هغه وخته پورې وچ کړی ؤ، ترڅو د اسراییلو قوم د هغه څخه تېر شو. هغوی ووېرېدل او نور یې دا جرات نه درلود چې د اسراییلو سره مخامخ شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua5_verse_1.mp3', '', 1761754199, 1761754199),
(38169, 'Joshua 5:2', 'Joshua', 5, 2, 'په هغه وخت کې څښتن یوشع ته وویل: «د بکرۍ د تیږې څخه چړې جوړې کړه او پاتې اسراییلیان سنت کړه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua5_verse_2.mp3', '', 1761754199, 1761754199),
(38170, 'Joshua 5:3', 'Joshua', 5, 3, 'نو څنګه چې څښتن حکم کړی ؤ، یوشع هماغسې وکړل او اسراییلیان یې په هغه ځای کې سنت کړل چې د سنت ګیرۍ د غونډۍ په نوم یاد شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua5_verse_3.mp3', '', 1761754199, 1761754199),
(38171, 'Joshua 5:4', 'Joshua', 5, 4, 'نو په دې خاطر هغه داسې وکړل. هغه ټول نارینه یعنې ټول جنګي کسان چې د مصر څخه راوتلي وو، د سفر په دوران کې په دښته کې مړه شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua5_verse_4.mp3', '', 1761754199, 1761754199),
(38172, 'Joshua 5:5', 'Joshua', 5, 5, 'هغه خلک چې د مصر څخه راوتلي وو هغوی ټول سنت شوي وو، خو هغه ټول خلک چې د سفر په دوران کې په دښته کې زېږېدلي وو، هغوی سنت شوي نه وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua5_verse_5.mp3', '', 1761754199, 1761754199),
(38173, 'Joshua 5:6', 'Joshua', 5, 6, 'اسراییلیانو څلوېښت کاله په دښته کې سفر وکړ، تر هغې چې ټول خلک یعنې د قوم ټول جنګي کسان چې د مصر څخه راووتل مړه شول، ځکه چې د څښتن د امر څخه یې سرغړونه کړې وه. لکه څنګه چې څښتن قسم خوړلی ؤ، هغوی ته اجازه ورنه کړای شوه چې هغه غني او حاصلخېزه ځمکه وویني چې د هغو د نیکونو سره یې وعده کړې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua5_verse_6.mp3', '', 1761754199, 1761754199),
(38174, 'Joshua 5:7', 'Joshua', 5, 7, 'د دغو خلکو زامن هېڅکله سنت شوي نه وو او دا هغه نوی نسل ؤ چې یوشع سنت کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua5_verse_7.mp3', '', 1761754199, 1761754199),
(38175, 'Joshua 5:8', 'Joshua', 5, 8, 'کله چې د اسراییلو ټول نارینه سنت شول، هغوی تر هغې پورې په کمپ کې پاتې شول، ترڅو چې زخمونه یې روغ شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua5_verse_8.mp3', '', 1761754199, 1761754199),
(38176, 'Joshua 5:9', 'Joshua', 5, 9, 'څښتن یوشع ته وویل: «دا زما د قوم دپاره د شرم خبره وه چې په مصر کې دې غلامان وي، خو ما نن هغه رسوایي لېرې کړه.» نو اسراییلیانو دغه ځای د جلجال په نوم یاد کړ او تر اوسه پورې په دې نوم یادیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua5_verse_9.mp3', '', 1761754199, 1761754199),
(38177, 'Joshua 5:10', 'Joshua', 5, 10, 'کله چې اسراییلیانو په جلجال کې اریحا ته نژدې په ډاګ کې خېمې ودرولې، هغوی د میاشتې د څوارلسمې ورځې په ماښام د فسحې اختر ولمانځه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua5_verse_10.mp3', '', 1761754199, 1761754199),
(38178, 'Joshua 5:11', 'Joshua', 5, 11, 'راتلونکې ورځ اول ځل ؤ چې هغوی د کنعان د محصولاتو څخه خواړه وخوړل یعنې وریتې شوې غلې دانې او فطیره ډوډۍ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua5_verse_11.mp3', '', 1761754199, 1761754199),
(38179, 'Joshua 5:12', 'Joshua', 5, 12, 'د هماغې ورځې څخه د خدای له خوا د من رالېږل بند شول او د اسراییلو دپاره نور من نه پیدا کېده. د هماغه وخت څخه هغوی هغه څه خوړل چې په کنعان کې پیدا کېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua5_verse_12.mp3', '', 1761754199, 1761754199),
(38180, 'Joshua 5:13', 'Joshua', 5, 13, 'یو وخت یوشع اریحا ته نژدې ؤ، چې ناڅاپه یې یو سړی ولیده چې د هغه مخې ته ولاړ ؤ او په لاس کې یې توره وه. یوشع هغه ته ورغی او پوښتنه یې ترې وکړه: «ته زمونږ په خوا یې که زمونږ د دښمنانو په خوا؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua5_verse_13.mp3', '', 1761754199, 1761754199),
(38181, 'Joshua 5:14', 'Joshua', 5, 14, 'هغه په ځواب کې وویل: «هېڅ یو نه، زه اوس د څښتن د لښکر د قوماندان په توګه راغلی یم.» بیا یوشع په ځمکه باندې پړمخې پرېوت او ویې ویل: «صاحبه، زه ستاسو خدمتګار یم. زما څخه څه غواړئ چې ویې کړم؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua5_verse_14.mp3', '', 1761754199, 1761754199),
(38182, 'Joshua 5:15', 'Joshua', 5, 15, 'د څښتن د لښکر قوماندان هغه ته وویل: «خپلې څپلۍ وباسه، ځکه چې ته په سپېڅلې ځمکې باندې ولاړ یې.» او یوشع همداسې وکړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua5_verse_15.mp3', '', 1761754199, 1761754199),
(38183, 'Psalms 113:1', 'Psalms', 113, 1, 'د څښتن ثنا او صفت وکړئ! ای بندګانو د څښتن، د هغه ثنا او صفت وکړئ ثنا او صفت وکړئ د هغه د نامه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms113_verse_1.mp3', '', 1761754199, 1761754199),
(38184, 'Psalms 113:2', 'Psalms', 113, 2, 'وي دې ثنا او صفت د څښتن د نامه له همدا‌اوس نه تر ابده پورې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms113_verse_2.mp3', '', 1761754199, 1761754199),
(38185, 'Psalms 113:3', 'Psalms', 113, 3, 'د لمرخاته نه تر لمر پرېوتولو پورې ثنا او صفت دې وشي د څښتن د نامه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms113_verse_3.mp3', '', 1761754199, 1761754199),
(38186, 'Psalms 113:4', 'Psalms', 113, 4, 'ټولو قومونو کې اوچت دی څښتن د هغه جلال له اسمانونو لوړ دی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms113_verse_4.mp3', '', 1761754199, 1761754199),
(38187, 'Psalms 113:5', 'Psalms', 113, 5, 'څوک دی بل داسې زمونږ د څښتن خدای په شان چې په اوچت ځای کې وي په تخت باندې ناست', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms113_verse_5.mp3', '', 1761754199, 1761754199),
(38188, 'Psalms 113:6', 'Psalms', 113, 6, 'خو شي راټیټ به هغه چې اسمانونه او ځمکه وګوري؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms113_verse_6.mp3', '', 1761754199, 1761754199),
(38189, 'Psalms 113:7', 'Psalms', 113, 7, 'غریبان پورته کوي هغه له خاورو ځینې او له نېستۍ نه خلاصوي محتاجان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms113_verse_7.mp3', '', 1761754199, 1761754199),
(38190, 'Psalms 113:8', 'Psalms', 113, 8, 'کښېنوي هغوی د شاهزادګانو سره د خپل قوم د شاهزادګانو سره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms113_verse_8.mp3', '', 1761754199, 1761754199),
(38191, 'Psalms 113:9', 'Psalms', 113, 9, 'شنډې ښځې ته اولاد ورکوي او خوشحالوي هغه په خپل کور کې د څښتن ثنا او صفت وکړئ!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms113_verse_9.mp3', '', 1761754199, 1761754199),
(38192, 'Psalms 124:1', 'Psalms', 124, 1, 'راکړئ ځواب ای د اسراییلو قومه څه به شوي وای په مونږه که څښتن نه وای طرفدار زمونږه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms124_verse_1.mp3', '', 1761754199, 1761754199),
(38193, 'Psalms 124:2', 'Psalms', 124, 2, 'که څښتن نه وای طرفدار زمونږه کله چې وکړه حمله خلکو په مونږ باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms124_verse_2.mp3', '', 1761754199, 1761754199),
(38194, 'Psalms 124:3', 'Psalms', 124, 3, 'کله چې دوی وو ډېر په قهر په مونږ دوی به تېر کړي وای ژوندي مونږه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms124_verse_3.mp3', '', 1761754199, 1761754199),
(38195, 'Psalms 124:4', 'Psalms', 124, 4, 'بیا به مونږ وړي وای سېلاب او لاندې کړي به اوبو وای مونږه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms124_verse_4.mp3', '', 1761754199, 1761754199),
(38196, 'Psalms 124:5', 'Psalms', 124, 5, 'او غړمبېدونکو څپو به وای ډوب کړي مونږه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms124_verse_5.mp3', '', 1761754199, 1761754199),
(38197, 'Psalms 124:6', 'Psalms', 124, 6, 'ثنا او صفت دې وي څښتن ته چې پرې یې نښودلو چې مونږه ښکار شو د دښمن د غاښو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms124_verse_6.mp3', '', 1761754199, 1761754199),
(38198, 'Psalms 124:7', 'Psalms', 124, 7, 'لکه مرغۍ په شان یو مونږه تښتېدلي د ښکاري له دامه هغه دام وشلېده او مونږه ترې وتښتېدو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms124_verse_7.mp3', '', 1761754199, 1761754199),
(38199, 'Psalms 124:8', 'Psalms', 124, 8, 'مونږ ته کومک رارسي د څښتن له خوا نه چا چې جوړ کړی دی اسمان او ځمکه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms124_verse_8.mp3', '', 1761754199, 1761754199),
(38200, 'Jeremiah 39:1', 'Jeremiah', 39, 1, 'د صدقياه د بادشاهۍ د نهم کال په لسمه مياشت د بابل نبوکدنضر بادشاه د خپل ټول لښکر سره راغلو او د يروشلم نه يې ګېره واچوله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah39_verse_1.mp3', '', 1761754199, 1761754199),
(38201, 'Jeremiah 39:2', 'Jeremiah', 39, 2, 'د صدقياه د بادشاهۍ په يوولسم کال د څلورمې مياشتې په نهمه ورځ هغوئ د ښار دېوالونه مات کړل او ښار ته ورننوتل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah39_verse_2.mp3', '', 1761754199, 1761754199),
(38202, 'Jeremiah 39:3', 'Jeremiah', 39, 3, 'د يروشلم د نيولو نه وروستو، د بابل د بادشاه ټول فوجى آفسران د ښار د مينځنۍ دروازې سره خپله ډېره واچوله چې په هغوئ کښې نرګل‌شراضر د سمګر، او نيبو‌سرسکيم سر لښکر، او نرګل‌شراضر د بادشاه مشاور، او نور ټول آفسران شامل وُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah39_verse_3.mp3', '', 1761754199, 1761754199),
(38203, 'Jeremiah 39:4', 'Jeremiah', 39, 4, 'کله چې صدقياه بادشاه او د هغۀ ټولو فوجيانو چې دا هر څۀ وليدل چې بابليان ښار ته راننوتل، نو هغوئ وتښتېدل. هغوئ شپه په شپه ښار پرېښودو او د شاهى باغ شا ته د دوه دېوالونو تر مينځه د دروازې د لارې نه بهر ووتل او د اُردن خوا ته روان شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah39_verse_4.mp3', '', 1761754199, 1761754199),
(38204, 'Jeremiah 39:5', 'Jeremiah', 39, 5, 'خو د بابليانو لښکر ورپسې وو او د يريحو سره نزدې يې په هوار مېدان صدقياه ونيولو. هغوئ هغه د بابل نبوکدنضر بادشاه له بوتلو، څوک چې په رِبله کښې د حمات په علاقه کښې وو. هلته د بابل بادشاه په صدقياه د سزا فېصله واوروله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah39_verse_5.mp3', '', 1761754199, 1761754199),
(38205, 'Jeremiah 39:6', 'Jeremiah', 39, 6, 'هغۀ په رِبله کښې د صدقياه په وړاندې د صدقياه زامن او د يهوداه ټول مشران حلال کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah39_verse_6.mp3', '', 1761754199, 1761754199),
(38206, 'Jeremiah 39:7', 'Jeremiah', 39, 7, 'بيا هغوئ د صدقياه سترګې راوويستلې او هغه يې د پيتلو په زنځيرونو وتړلو او بابل ته يې بندى بوتلو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah39_verse_7.mp3', '', 1761754199, 1761754199),
(38207, 'Jeremiah 39:8', 'Jeremiah', 39, 8, 'په دې دوران کښې بابليانو يروشلم، شاهى محل او د خلقو کورونه وسوزول او د ښار دېوالونه يې وران کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah39_verse_8.mp3', '', 1761754199, 1761754199),
(38208, 'Jeremiah 39:9', 'Jeremiah', 39, 9, 'بيا نبوزردان، د فوجيانو کمانډر هغه کسان چې ژوندى پاتې شوى وُو او کوم کسان چې بګوړه شوى وُو هغوئ يې بابل ته بنديوان بوتلل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah39_verse_9.mp3', '', 1761754199, 1761754199),
(38209, 'Jeremiah 39:10', 'Jeremiah', 39, 10, 'خو نبوزردان لږ څۀ غريبانان خلق په يهوداه کښې پرېښودل چا چې زمکه نۀ لرله، او هغۀ هغوئ ته پټى او د انګورو باغونه په حواله کړل چې د هغې خيال ساتى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah39_verse_10.mp3', '', 1761754199, 1761754199),
(38210, 'Jeremiah 39:11', 'Jeremiah', 39, 11, 'خو نبوکدنضر بادشاه فوجى آفسر نبوزردان ته دا حکم وکړو چې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah39_verse_11.mp3', '', 1761754199, 1761754199);